/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_user_addresses_after_insert` AFTER INSERT ON `tb_user_addresses` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_users`, `operation_date`,
         `table_description`, `operation_status`)
    VALUES
        ('tb_user_addresses', 'Create', USER(), CURRENT_TIMESTAMP,
         CONCAT(
             'Direccion creada. ID=', NEW.ID,
             ', user_ID=', NEW.user_ID,
             ', address_label=', NEW.address_label,
             ', recipient_name=', COALESCE(NEW.recipient_name, 'NULL'),
             ', recipient_phone=', COALESCE(NEW.recipient_phone, 'NULL'),
             ', delivery_instructions=', COALESCE(NEW.delivery_instructions, 'NULL'),
             ', latitude=', COALESCE(CAST(NEW.latitude AS CHAR), 'NULL'),
             ', longitude=', COALESCE(CAST(NEW.longitude AS CHAR), 'NULL'),
             ', is_default=', CAST(NEW.is_default AS UNSIGNED),
             ', status=', CAST(NEW.status AS UNSIGNED),
             ', creation_date=', NEW.creation_date,
             ', last_update=', COALESCE(CAST(NEW.last_update AS CHAR), 'NULL')
         ),
         b'1');
END */;;
