/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_user_payment_methods_after_update` AFTER UPDATE ON `tbd_user_payment_methods` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_users`, `operation_date`,
         `table_description`, `operation_status`)
    VALUES
        ('tbd_user_payment_methods', 'Update', USER(), NOW(),
         CONCAT('Método de pago de usuario modificado. ID=', NEW.ID,
                ' | user_ID: ', OLD.user_ID, ' -> ', NEW.user_ID,
                ' | payment_method_type_ID: ', OLD.payment_method_type_ID,
                    ' -> ', NEW.payment_method_type_ID,
                ' | provider: ', OLD.provider, ' -> ', NEW.provider,
                ' | label: ', COALESCE(OLD.label, 'NULL'), ' -> ',
                              COALESCE(NEW.label, 'NULL'),
                ' | is_default: ', OLD.is_default, ' -> ', NEW.is_default,
                ' | status: ', CAST(OLD.status AS UNSIGNED), ' -> ',
                               CAST(NEW.status AS UNSIGNED),
                ' | provider_method_ref: ',
                    IF(OLD.provider_method_ref <> NEW.provider_method_ref,
                       'actualizado', 'sin cambios'),
                ' | last_four: ',
                    IF(NOT (OLD.last_four <=> NEW.last_four),
                       'actualizado', 'sin cambios')),
         b'1');
END */;;
