CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertarProductosMasivos`(IN id_vendedor_1 INT, IN id_vendedor_2 INT)
BEGIN
    DECLARE i INT DEFAULT 1;
    
    -- 5000 productos para el primer vendedor
    WHILE i <= 5000 DO
        INSERT INTO tb_products (name, description, price, stock, id_user) 
        VALUES (CONCAT('Producto Vendedor A - ', i), 'Desc', 150.00, 10, id_vendedor_1);
        SET i = i + 1;
    END WHILE;
    
    -- 2000 productos para el segundo vendedor
    SET i = 1;
    WHILE i <= 2000 DO
        INSERT INTO tb_products (name, description, price, stock, id_user) 
        VALUES (CONCAT('Producto Vendedor B - ', i), 'Desc', 300.00, 5, id_vendedor_2);
        SET i = i + 1;
    END WHILE;
END ;;
DELIMITER ;
