CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertarProductosVendedor`(
    IN p_id_usuario INT, 
    IN p_cantidad INT, 
    IN p_prefijo VARCHAR(50)
)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_product_id INT;
    DECLARE v_cat_id INT;

    WHILE i <= p_cantidad DO
        -- 1. Insertar producto usando tus columnas exactas (incluyendo SKU único)
        INSERT INTO tb_products (SKU, name, description, current_price, current_stock, status) 
        VALUES (
            CONCAT('SKU-', p_id_usuario, '-', i, '-', FLOOR(RAND() * 99999)),
            CONCAT(p_prefijo, ' - Producto ', i), 
            'Descripción generada en simulación', 
            ROUND(50 + (RAND() * 950), 2), 
            FLOOR(1 + (RAND() * 100)),
            IF(RAND() < 0.10, b'0', b'1') -- 10% descontinuados
        );
        
        SET v_product_id = LAST_INSERT_ID();

        -- 2. Vincular producto con el vendedor
        INSERT INTO tbd_products_users_providers (user_ID, product_ID, type_ownership, status, avalaible_date)
        VALUES (p_id_usuario, v_product_id, 'Owner', b'1', NOW());

        -- 3. Asignarle una categoría aleatoria
        SELECT ID INTO v_cat_id FROM tbc_categories ORDER BY RAND() LIMIT 1;
        INSERT INTO tbd_products_categories (product_ID, category_ID)
        VALUES (v_product_id, v_cat_id);

        SET i = i + 1;
    END WHILE;
END ;;
DELIMITER ;
