CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cancelar_ordenes_pendientes`(IN p_dias INT)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_corte DATETIME;
    DECLARE v_total INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_dias IS NULL OR p_dias < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_dias debe ser un entero mayor o igual a 1';
    END IF;

    SET v_corte = NOW() - INTERVAL p_dias DAY;

    START TRANSACTION;
        INSERT INTO tb_order_cancellations (id_order, reason)
        SELECT id_order, CONCAT('Cancelacion automatica: sin pago despues de ', p_dias, ' dias')
        FROM tb_orders
        WHERE status = 'pending' AND created_at < v_corte;

        UPDATE tb_orders
        SET status = 'cancelled'
        WHERE status = 'pending' AND created_at < v_corte;
        SET v_total = ROW_COUNT();
    COMMIT;

    SELECT v_total AS ordenes_canceladas, v_corte AS fecha_corte;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
