CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_desactivar_carritos_inactivos`(IN p_dias INT)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_corte DATETIME;
    DECLARE v_total INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_dias IS NULL OR p_dias < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_dias debe ser un entero mayor o igual a 1';
    END IF;

    SET v_corte = NOW() - INTERVAL p_dias DAY;

    START TRANSACTION;
        UPDATE tb_carts
        SET status = b'0'
        WHERE status = b'1' AND COALESCE(last_update, creation_date) < v_corte;
        SET v_total = ROW_COUNT();
    COMMIT;

    SELECT v_total AS carritos_desactivados, v_corte AS fecha_corte;
END ;;
DELIMITER ;
