CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_poblar_productos_vendedor`(
    IN p_id_usuario INT UNSIGNED,
    IN p_cantidad   INT,
    IN p_prefijo    VARCHAR(50),
    IN p_pct_desc   DECIMAL(5,2)
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_i      INT DEFAULT 0;
    DECLARE v_cats   INT;
    DECLARE v_start  INT;
    DECLARE v_offset INT;
    DECLARE v_lote   VARCHAR(12);
    DECLARE v_desc   INT DEFAULT 0;
    DECLARE v_inicio DATETIME DEFAULT NOW();
    DECLARE v_pid    INT UNSIGNED;
    DECLARE v_cat_id INT UNSIGNED;
    DECLARE v_cat_nm VARCHAR(120);
    DECLARE v_status BIT(1);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SET p_prefijo  = IFNULL(NULLIF(p_prefijo, ''), 'Producto');
    SET p_pct_desc = IFNULL(p_pct_desc, 10);

    IF NOT EXISTS (SELECT 1 FROM tb_users WHERE ID = p_id_usuario) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El id_usuario no existe en tb_users';
    END IF;
    IF p_cantidad IS NULL OR p_cantidad < 1 OR p_cantidad > 100000 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'cantidad debe estar entre 1 y 100000';
    END IF;
    IF p_pct_desc < 0 OR p_pct_desc > 100 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'pct_descontinuados debe estar entre 0 y 100';
    END IF;

    SELECT COUNT(*) INTO v_cats FROM tbc_categories WHERE status = b'1';
    IF v_cats = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay categorias activas en tbc_categories';
    END IF;

    SET v_start = fn_random_int(0, v_cats - 1);
    SET v_lote  = DATE_FORMAT(NOW(), '%y%m%d%H%i%s');

    START TRANSACTION;
    WHILE v_i < p_cantidad DO
        SET v_i      = v_i + 1;
        SET v_offset = MOD(v_start + v_i, v_cats);

        SELECT ID, name INTO v_cat_id, v_cat_nm
        FROM tbc_categories WHERE status = b'1'
        ORDER BY ID LIMIT 1 OFFSET v_offset;

        SET v_status = fn_pick_status(100 - p_pct_desc);
        IF v_status = b'0' THEN SET v_desc = v_desc + 1; END IF;

        INSERT INTO tb_products (SKU, name, description, current_price, current_stock, status)
        VALUES (CONCAT('SKU-', p_id_usuario, '-', v_lote, '-', LPAD(v_i, 6, '0')),
                CONCAT(p_prefijo, ' - ', v_cat_nm, ' #', LPAD(v_i, 5, '0')),
                CONCAT('Producto simulado de la categoria ', v_cat_nm),
                ROUND(10 + RAND() * 1990, 2),
                fn_random_int(0, 500),
                v_status);
        SET v_pid = LAST_INSERT_ID();

        INSERT INTO tbd_products_users_providers (user_ID, product_ID, type_ownership, status, avalaible_date)
        VALUES (p_id_usuario, v_pid, 'Owner', b'1', NOW());

        INSERT INTO tbd_products_categories (product_ID, category_ID)
        VALUES (v_pid, v_cat_id);

        IF MOD(v_i, 500) = 0 THEN
            COMMIT;
            START TRANSACTION;
        END IF;
    END WHILE;
    COMMIT;

    SELECT p_id_usuario AS vendedor_id, p_cantidad AS insertados, v_desc AS descontinuados,
           p_cantidad - v_desc AS disponibles,
           TIMESTAMPDIFF(SECOND, v_inicio, NOW()) AS segundos, USER() AS ejecutado_por;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
