CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simular_usuarios`(
    IN p_cantidad    INT,
    IN p_genero      VARCHAR(30),
    IN p_pais        VARCHAR(5),
    IN p_edad_min    INT,
    IN p_edad_max    INT,
    IN p_pct_activos DECIMAL(5,2)
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_i        INT DEFAULT 0;
    DECLARE v_emin     INT;
    DECLARE v_emax     INT;
    DECLARE v_pct      DECIMAL(5,2);
    DECLARE v_gen      VARCHAR(30);
    DECLARE v_pais     CHAR(2);
    DECLARE v_nombre   VARCHAR(50);
    DECLARE v_apellido VARCHAR(50);
    DECLARE v_lote     VARCHAR(14);
    DECLARE v_uid      INT UNSIGNED;
    DECLARE v_status   BIT(1);
    DECLARE v_activos  INT DEFAULT 0;
    DECLARE v_inicio   DATETIME DEFAULT NOW();

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_cantidad IS NULL OR p_cantidad < 1 OR p_cantidad > 100000 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'cantidad debe estar entre 1 y 100000';
    END IF;

    SET v_emin = IFNULL(p_edad_min, 18);
    SET v_emax = IFNULL(p_edad_max, 60);
    SET v_pct  = IFNULL(p_pct_activos, 100);

    IF v_emin < 13 OR v_emax > 110 OR v_emin > v_emax THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Rango de edad invalido';
    END IF;
    IF v_pct < 0 OR v_pct > 100 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'pct_activos debe estar entre 0 y 100';
    END IF;

    SET v_lote = DATE_FORMAT(NOW(), '%y%m%d%H%i%s');

    START TRANSACTION;
    WHILE v_i < p_cantidad DO
        SET v_i = v_i + 1;

        IF p_genero IS NULL OR p_genero = '' OR p_genero = '*' THEN
            SET v_gen = ELT(fn_random_int(1, 3), 'hombre', 'mujer', 'Prefiero no decirlo');
        ELSE
            SET v_gen = p_genero;
        END IF;

        IF p_pais IS NULL OR p_pais = '' OR p_pais = '*' THEN
            SET v_pais = fn_random_country();
        ELSE
            SET v_pais = UPPER(LEFT(p_pais, 2));
        END IF;

        SET v_nombre   = fn_random_given_name(v_gen);
        SET v_apellido = fn_random_family_name();
        SET v_status   = fn_pick_status(v_pct);
        IF v_status = b'1' THEN SET v_activos = v_activos + 1; END IF;

        INSERT INTO tb_users (email, nick, password, creation_date, status)
        VALUES (
            CONCAT(LOWER(v_nombre), '.', LOWER(v_apellido), '.', v_lote, '_', v_i, '@simulado.test'),
            CONCAT(v_nombre, ' ', v_apellido, ' ', v_lote, '_', v_i),
            SHA2(CONCAT('PassSim_', v_lote, '_', v_i), 256),
            NOW(),
            v_status
        );
        SET v_uid = LAST_INSERT_ID();

        INSERT INTO tb_people (
            user_ID, courtesy_title, given_names, family_names,
            birth_date, gender, country_code, phone, status
        )
        VALUES (
            v_uid,
            IF(v_gen = 'hombre', 'Sr.', IF(v_gen = 'mujer', 'Sra.', NULL)),
            v_nombre,
            v_apellido,
            fn_random_birth_date(v_emin, v_emax),
            v_gen,
            v_pais,
            CONCAT('55', LPAD(fn_random_int(10000000, 99999999), 8, '0')),
            v_status
        );

        IF MOD(v_i, 500) = 0 THEN
            COMMIT;
            START TRANSACTION;
        END IF;
    END WHILE;
    COMMIT;

    SELECT p_cantidad AS solicitados,
           v_activos AS activos,
           p_cantidad - v_activos AS inactivos,
           TIMESTAMPDIFF(SECOND, v_inicio, NOW()) AS segundos,
           USER() AS ejecutado_por;
END ;;
DELIMITER ;
